// Trie les images du dossier courant et désigne la photo principale.
const folder = $('Boucle dossiers').first().json;

const slug = String(folder.name || 'produit')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'produit';

const images = $input.all()
  .filter((i) => typeof i.json.mimeType === 'string' && i.json.mimeType.startsWith('image/'))
  .sort((a, b) => String(a.json.name).localeCompare(String(b.json.name), 'fr', { numeric: true }));

// Dossier vide : on renvoie un marqueur, le dossier sera ignoré (pas de renommage).
if (images.length === 0) {
  return [{ json: { empty: true, folderId: folder.id, folderName: folder.name } }];
}

// Photo principale : nom contenant main / principale / cover / 1, sinon la première.
const MAIN_RE = /(^|[\s_.-])(main|principale?|cover|couverture|0?1)([\s_.-]|$)/i;
let mainIndex = images.findIndex((i) => MAIN_RE.test(String(i.json.name).replace(/\.[^.]+$/, '')));
if (mainIndex === -1) mainIndex = 0;

// La principale passe en tête : elle est donc toujours l'item [0] de ce nœud.
const ordered = [images[mainIndex], ...images.filter((_, idx) => idx !== mainIndex)];

return ordered.map((img, idx) => ({
  json: {
    id: img.json.id,
    name: img.json.name,
    mimeType: img.json.mimeType,
    isMain: idx === 0,
    position: idx + 1,
    newName: `${slug}-${String(idx + 1).padStart(2, '0')}.webp`,
    folderId: folder.id,
    folderName: folder.name,
    empty: false,
  },
}));

// Normalise la réponse de l'API Hugging Face.
// Selon le modèle / le provider, l'inference API renvoie soit :
//   - une image binaire (PNG détouré, fond transparent)
//   - soit du JSON : [{ label, score, mask: "<png en base64>" }]  (pipeline image-segmentation)
// Ce nœud produit toujours un item exploitable par la suite du workflow.

const items = $input.all();
const original = $('Télécharger la photo principale').first().binary.data;

const isImage = (b) => b && String(b.mimeType || '').startsWith('image/');

// --- Cas 1 : Hugging Face a renvoyé directement l'image détourée
for (const it of items) {
  const bin = it.binary || {};
  const img = Object.values(bin).find(isImage);
  if (img) {
    return [{ json: { hfMode: 'cutout' }, binary: { data: img } }];
  }
}

// --- Cas 2 : réponse JSON (un item par entrée du tableau renvoyé par HF)
const rows = [];
for (let idx = 0; idx < items.length; idx++) {
  let j = items[idx].json;
  const bin = items[idx].binary || {};
  const keys = Object.keys(bin);
  if ((!j || Object.keys(j).length === 0) && keys.length) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(idx, keys[0]);
      j = JSON.parse(buf.toString('utf8'));
    } catch (e) {
      // ignoré : on tombera sur l'erreur explicite plus bas
    }
  }
  if (Array.isArray(j)) rows.push(...j);
  else if (j) rows.push(j);
}

const erreur = rows.find((r) => r && r.error);
if (erreur) {
  throw new Error('Hugging Face a renvoyé une erreur : ' + JSON.stringify(erreur.error));
}

const masques = rows
  .filter((r) => r && typeof r.mask === 'string' && r.mask.length > 100)
  .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

const choisi = masques.find((r) => !/back(ground)?|bg|fond/i.test(String(r.label || ''))) || masques[0];

if (!choisi) {
  throw new Error(
    'Réponse Hugging Face inattendue (ni image, ni masque). Extrait : ' +
      JSON.stringify(rows).slice(0, 300),
  );
}

const masque = await this.helpers.prepareBinaryData(
  Buffer.from(choisi.mask, 'base64'),
  'masque.png',
  'image/png',
);

// data = photo d'origine, mask = masque alpha -> le nœud suivant fait le détourage
return [{ json: { hfMode: 'mask', label: choisi.label ?? null }, binary: { data: original, mask: masque } }];

// Réunit dans un seul item : le fond (template Y2K) + le vêtement détouré,
// et calcule la position pour centrer le vêtement sur le fond.
const cfg = $('Config').first().json;

const vetement = $('Redimensionner le vêtement').first().binary.data;
const fond = $input.first().binary.background;

const info = $('Mesurer le vêtement').first().json;
const largeurVetement = Number(info?.size?.width ?? info?.width ?? 0);
const hauteurVetement = Number(info?.size?.height ?? info?.height ?? 0);

const largeurFond = Number(cfg.TEMPLATE_LARGEUR) || 1500;
const hauteurFond = Number(cfg.TEMPLATE_HAUTEUR) || 1500;

const posX = Math.max(0, Math.round((largeurFond - largeurVetement) / 2));
const posY = Math.max(0, Math.round((hauteurFond - hauteurVetement) / 2));

return [{
  json: { posX, posY, largeurVetement, hauteurVetement, largeurFond, hauteurFond },
  binary: { data: fond, cutout: vetement },
}];

// Récapitulatif des dossiers validés pendant cette exécution.
const dossiers = $input.all()
  .filter((i) => i.json && i.json.name && i.json.empty !== true)
  .map((i) => i.json.name);

return [{
  json: {
    event: 'lilog_images_ready',
    prefix: $('Config').first().json.PREFIXE_TRAITE,
    foldersProcessed: dossiers.length,
    folders: dossiers,
    finishedAt: new Date().toISOString(),
  },
}];
